    private static readonly Dictionary<ushort, int> PkToIndex = BuildReverse();

    /// <summary>Essentials symbol for a given IF dex index, or null when the slot is empty.</summary>
    public static string? GetSymbol(int idNumber) => (uint)idNumber < (uint)SymbolByIndex.Length ? SymbolByIndex[idNumber] : null;

    /// <summary>PKHeX species id for a given IF dex index, or 0 when unknown.</summary>
    public static ushort GetSpecies(int idNumber)
    {
        var s = GetSymbol(idNumber);
        return s is null ? (ushort)0 : IFNameLookup.GetSpecies(s);
    }

    /// <summary>IF dex index for a PKHeX species id, or -1 when the species is not part of IF.</summary>
    public static int GetIndex(ushort pkSpecies) => PkToIndex.TryGetValue(pkSpecies, out var v) ? v : -1;

    public static bool IsValid(int idNumber) => idNumber >= 1 && idNumber <= Count && GetSymbol(idNumber) is not null;

    private static Dictionary<ushort, int> BuildReverse()
    {
        var d = new Dictionary<ushort, int>();
        for (int i = 1; i <= Count; i++)
        {
            var pk = GetSpecies(i);
            if (pk != 0)
                d.TryAdd(pk, i);
        }
        return d;
    }
